+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import org.junit.jupiter.api.AfterAll;
+import org.junit.jupiter.api.BeforeAll;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+
+import com.microsoft.playwright.Browser;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.Playwright;
+import com.microsoft.playwright.options.AriaRole;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = "vaadin.launch-browser=false")
+class ContactViewBrowserTest {
+
+    private static Playwright playwright;
+    private static Browser browser;
+
+    @LocalServerPort
+    private int port;
+
+    @BeforeAll
+    static void startBrowser() {
+        playwright = Playwright.create();
+        browser = playwright.chromium().launch();
+    }
+
+    @AfterAll
+    static void stopBrowser() {
+        browser.close();
+        playwright.close();
+    }
+
+    @Test
+    void sendAndLeave() {
+        Page page = browser.newPage();
+        page.setDefaultTimeout(60000);
+        page.navigate("http://localhost:" + port + "/contact");
+        assertThat(page.locator("h1")).hasText("Contact");
+
+        var name = page.getByLabel("Name");
+        var phone = page.getByLabel("Phone");
+        var message = page.getByLabel("Message");
+        var send = page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send"));
+
+        send.click();
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+        assertThat(page.locator("vaadin-email-field")).hasAttribute("invalid", "");
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+
+        name.fill("Eve");
+        phone.fill("555");
+        message.fill("Hi there");
+        phone.press("Enter");
+        assertThat(page.locator("vaadin-notification-card")).containsText("Message sent");
+        assertThat(page.locator("vaadin-notification-card")).hasCount(1);
+        assertThat(page.getByText("Name is required")).isHidden();
+        assertThat(name).hasValue("");
+        assertThat(send).isDisabled();
+        assertThat(page.locator("vaadin-grid-cell-content").getByText("Hi there").first()).isAttached();
+        name.fill("x");
+        assertThat(send).isEnabled();
+
+        page.getByText("About").click();
+        assertThat(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing"))).isVisible();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+        assertThat(page.locator("h1")).hasText("Contact");
+        page.getByText("About").click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+        assertThat(page.locator("h1")).hasText("About");
+
+        // Form was left with input; the new view starts empty, so leaving is not interrupted
+        page.goBack();
+        assertThat(page.locator("h1")).hasText("Contact");
+        page.getByText("About").click();
+        assertThat(page.locator("h1")).hasText("About");
+
+        // Browser history navigation with input also asks
+        page.goBack();
+        assertThat(page.locator("h1")).hasText("Contact");
+        page.getByLabel("Name").fill("y");
+        page.goForward();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page.getByLabel("Name")).hasValue("y");
+        page.getByText("About").click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+        assertThat(page.locator("h1")).hasText("About");
+    }
+}
