+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void open() {
+        navigate(ContactView.class);
+        name = $(TextField.class).withCaption("Name").single();
+        phone = $(TextField.class).withCaption("Phone").single();
+        email = $(EmailField.class).withCaption("Email").single();
+        message = $(TextArea.class).withCaption("Message").single();
+        send = $(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<ContactMessage> grid() {
+        return $(Grid.class).single();
+    }
+
+    @Test
+    void initialState() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue(send.isEnabled());
+        assertTrue(name.isEmpty() && email.isEmpty() && phone.isEmpty() && message.isEmpty());
+    }
+
+    @Test
+    void emptyFormShowsAllErrors() {
+        int rows = test(grid()).size();
+        test(send).click();
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals(rows, test(grid()).size());
+        assertTrue($(Notification.class).all().isEmpty());
+    }
+
+    @Test
+    void invalidEmailAndLongMessage() {
+        test(name).setValue("Ann");
+        test(email).setValue("not-an-email");
+        test(message).setValue("x".repeat(501));
+        test(send).click();
+        assertFalse(name.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals("not-an-email", email.getValue());
+    }
+
+    @Test
+    void phoneAloneIsEnoughAndSendDisablesUntilEdit() {
+        test(name).setValue("Bob");
+        test(phone).setValue("12345");
+        test(message).setValue("x".repeat(500));
+        test(send).click();
+        assertTrue(test($(Notification.class).last()).getText().contains("Message sent"));
+        assertEquals("Bob", test(grid()).getRow(0).name());
+        assertTrue(name.isEmpty() && email.isEmpty() && phone.isEmpty() && message.isEmpty());
+        assertFalse(send.isEnabled());
+        test(phone).setValue("1");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void enterSendsAndListSurvivesNavigation() {
+        test(name).setValue("Carol");
+        test(email).setValue("carol@example.com");
+        test(message).setValue("Hello");
+        fireShortcut(Key.ENTER);
+        assertEquals("Carol", test(grid()).getRow(0).name());
+
+        test($(RouterLink.class).withText("About").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertTrue($(Dialog.class).all().isEmpty());
+
+        navigate(ContactView.class);
+        assertEquals("Carol", test(grid()).getRow(0).name());
+    }
+
+    @Test
+    void leavingWithInputAsks() {
+        test(name).setValue("Dave");
+        test($(RouterLink.class).withText("About").single()).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertTrue($(Dialog.class).all().isEmpty() || !$(Dialog.class).single().isOpened());
+        assertEquals("Dave", name.getValue());
+
+        com.vaadin.flow.component.UI.getCurrent().navigate(AboutView.class);
+        assertInstanceOf(ContactView.class, getCurrentView());
+        test($(Button.class).withText("Discard").single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
